set-variable.value:
#[%dw 2.0
output application/java

var record = vars.db[0] default {}

---
"<!DOCTYPE html>
<html>

<head>

<meta charset='UTF-8'/>

<title>Withdrawal Successful</title>

<style>

body{
margin:0;
padding:0;
background:#eef3f8;
font-family:Segoe UI,Arial,sans-serif;
}

.container{
width:700px;
margin:30px auto;
background:#fff;
border-radius:15px;
overflow:hidden;
box-shadow:0 8px 30px rgba(0,0,0,.15);
}

.header{
background:linear-gradient(135deg,#003366,#0059b3);
padding:35px;
text-align:center;
color:#fff;
}

.header h1{
margin:0;
font-size:32px;
}

.header p{
margin-top:8px;
font-size:14px;
}

.success{
padding:35px;
text-align:center;
}

.success h2{
color:#dc2626;
margin-top:15px;
}

.circle{
width:90px;
height:90px;
line-height:90px;
border-radius:50%;
background:#ef4444;
color:white;
font-size:45px;
margin:auto;
}

.card{
margin:25px;
border:1px solid #ddd;
border-radius:12px;
overflow:hidden;
}

.card-title{
background:#003366;
color:white;
padding:16px;
font-size:20px;
font-weight:bold;
}

table{
width:100%;
border-collapse:collapse;
}

td{
padding:15px;
border-bottom:1px solid #eee;
}

td:first-child{
font-weight:bold;
background:#fafafa;
width:40%;
}

.amount{
color:#dc2626;
font-size:22px;
font-weight:bold;
}

.balance{
color:#16a34a;
font-size:22px;
font-weight:bold;
}

.status{
display:inline-block;
padding:6px 15px;
background:#d1fae5;
color:#15803d;
border-radius:25px;
font-weight:bold;
}

.notice{
margin:25px;
background:#fff7ed;
border-left:5px solid orange;
padding:20px;
border-radius:8px;
line-height:28px;
}

.footer{
background:#003366;
color:white;
text-align:center;
padding:30px;
font-size:13px;
line-height:24px;
}

</style>

</head>

<body>

<div class='container'>

<div class='header'>

<h1>🏦 " ++ (record.BANKNAME default "REAL BANK") ++ "</h1>

<p>Secure • Trusted • Digital Banking</p>

</div>

<div class='success'>

<div class='circle'>⬇</div>

<h2>Withdrawal Successful</h2>

<p>Your withdrawal transaction has been completed successfully.</p>

</div>

<div class='card'>

<div class='card-title'>

Transaction Summary

</div>

<table>

<tr>

<td>Customer Name</td>

<td>" ++ (record.FULLNAME default "N/A") ++ "</td>

</tr>

<tr>

<td>Account Number</td>

<td>" ++ (record.ACCOUNTNUMBER default vars.accountNumber) ++ "</td>

</tr>

<tr>

<td>Transaction ID</td>

<td>" ++ vars.transactionId ++ "</td>

</tr>

<tr>

<td>Transaction Type</td>

<td>WITHDRAW</td>

</tr>

<tr>

<td>Amount Debited</td>

<td class='amount'>₹ " ++ ((vars.amount default 0) as String) ++ "</td>

</tr>

<tr>

<td>Available Balance</td>

<td class='balance'>₹ " ++ ((vars.leftBalance.balance default 0) as String) ++ "</td>

</tr>

<tr>

<td>Date & Time</td>

<td>" ++ ((now()) as String {format:'dd MMM yyyy hh:mm:ss a'}) ++ "</td>

</tr>

<tr>

<td>Status</td>

<td><span class='status'>SUCCESS</span></td>

</tr>

</table>

</div>

<div class='notice'>

<b>Security Tips</b>

<ul>

<li>Never share your OTP.</li>

<li>Never disclose your ATM PIN.</li>

<li>Report suspicious transactions immediately.</li>

<li>Enable SMS and Email Alerts.</li>

</ul>

</div>

<div class='footer'>

<b>Real Bank</b><br/>

Customer Care : +91 9494207062<br/>

support@realbank.com<br/><br/>

© 2026 Real Bank. All Rights Reserved.<br/>

This is a system generated email.

</div>

</div>

</body>

</html>"]
